'use client';

import { definePlatePlugin } from 'platejs/react';

import { FixedToolbar } from '@/registry/components/editor/fixed-toolbar';
import { FixedToolbarButtons } from '@/registry/components/editor/fixed-toolbar-classic-buttons';

export const FixedToolbarKit = [
  definePlatePlugin('fixedToolbar', {
    render: {
      beforeEditable: () => (
        <FixedToolbar>
          <FixedToolbarButtons />
        </FixedToolbar>
      ),
    },
  }),
];
